r"""Runtime patch for litellm's SageMaker event-stream decoder (ENG-3400).

litellm's ``AWSEventStreamDecoder`` (``litellm/llms/sagemaker/common_utils.py``)
turns AWS SageMaker ``PayloadPart`` events into SSE (``"data: {...}\\n\\n"``)
frames and JSON-parses them. For each part it strips one leading ``"data: "``,
deletes every ``"\\n\\n"``, appends the rest to a running buffer and retries
``json.loads`` on the whole buffer -- and it only resets that buffer after a
successful parse. SageMaker part boundaries are not aligned with SSE frames,
so a part that splits the ``"data: "`` prefix, or carries more than one frame,
leaves unparseable text in the buffer and every later frame is appended to it
and lost. ``"data: [DONE]"`` (vLLM's terminator) never parses either, so each
stream also ends with a logged ERROR.

The buggy code is identical across every litellm version this repo pins and
the upstream PR (BerriAI/litellm#31598) is unmerged, so this module fixes it
at runtime. It keeps litellm's own ``iter_bytes``/``aiter_bytes`` loops and
error handling untouched and only re-frames the byte stream they read: SSE
frames are reassembled on their ``"\\n\\n"`` delimiter, ``[DONE]`` and
non-JSON frames are dropped, and each remaining frame is re-emitted as its own
``PayloadPart`` carrying exactly one bare JSON body -- the one input litellm's
loop already handles correctly. Non-``PayloadPart`` events (e.g. model
exceptions) are passed through byte-for-byte.

Only decoders built with ``is_messages_api=True`` -- the OpenAI-compatible
SSE path used by ``sagemaker_chat`` -- are re-framed. The non-chat
``sagemaker`` path carries container-specific shapes (e.g. newline-delimited
JSON) and is left exactly as litellm ships it.

Known limitation, inherited from litellm: its async loop keeps a valid JSON
object that is not a chat chunk (e.g. ``{"error": ...}``) in its buffer, so
frames after such an object are still lost. vLLM only sends ``[DONE]`` after
an error object, so in practice nothing follows it.

Not to be confused with ``litellm.llms.bedrock.chat.invoke_handler.
AWSEventStreamDecoder``, an unrelated Bedrock class this patch does not touch.
"""

from __future__ import annotations

import codecs
import functools
import json
import struct
from binascii import crc32
from typing import (
    TYPE_CHECKING,
    Any,
    AsyncIterator,
    Callable,
    Iterator,
    Optional,
)

import structlog

if TYPE_CHECKING:
    from botocore.eventstream import EventStreamMessage
    from litellm.llms.sagemaker.common_utils import AWSEventStreamDecoder

structlogger = structlog.get_logger()

_SSE_FRAME_DELIMITER = "\n\n"
_SSE_DATA_PREFIX_WITH_SPACE = "data: "
_SSE_DATA_PREFIX = "data:"
_SSE_DONE_MARKER = "[DONE]"

# Event-stream wire format: prelude = total_length (4) + headers_length (4) +
# prelude CRC (4); a message ends with a 4-byte message CRC.
_PRELUDE_LENGTH = 12
_MESSAGE_CRC_LENGTH = 4
_MIN_MESSAGE_LENGTH = _PRELUDE_LENGTH + _MESSAGE_CRC_LENGTH
# botocore's own header/payload caps; anything larger it rejects anyway.
_MAX_MESSAGE_LENGTH = _MIN_MESSAGE_LENGTH + 128 * 1024 + 24 * 1024 * 1024
_HEADER_TYPE_STRING = 7
_PAYLOAD_PART_HEADERS = (
    (":message-type", "event"),
    (":event-type", "PayloadPart"),
    (":content-type", "application/octet-stream"),
)

_sagemaker_patch_installed = False
_ORIGINAL_ITER_BYTES: Optional[Callable[..., Any]] = None
_ORIGINAL_AITER_BYTES: Optional[Callable[..., Any]] = None


class _SageMakerSSEFrameAssembler:
    r"""Reassembles raw ``PayloadPart`` text into complete SSE frames.

    Accumulates raw, unstripped text and only splits it on the ``"\\n\\n"``
    frame delimiter, so the ``data:`` prefix is stripped and ``[DONE]``
    detected only once a frame is complete. A part boundary inside the
    prefix, or several frames in one part, therefore cannot corrupt anything.
    """

    def __init__(self) -> None:
        self._carry: str = ""

    def feed(self, raw_text: str) -> Iterator[str]:
        """Yield the body of each frame completed by `raw_text`.

        Frames whose body is empty or ``[DONE]`` are swallowed.
        """
        *complete_segments, self._carry = (self._carry + raw_text).split(
            _SSE_FRAME_DELIMITER
        )
        for segment in complete_segments:
            content = self._strip_prefix(segment)
            if content is not None:
                yield content

    def flush(self) -> Iterator[str]:
        """Yield the body of a final frame the stream never delimited."""
        content = self._strip_prefix(self._carry)
        self._carry = ""
        if content is not None:
            yield content

    @staticmethod
    def _strip_prefix(segment: str) -> Optional[str]:
        segment = segment.lstrip("\n")
        if segment.startswith(_SSE_DATA_PREFIX_WITH_SPACE):
            segment = segment[len(_SSE_DATA_PREFIX_WITH_SPACE) :]
        elif segment.startswith(_SSE_DATA_PREFIX):
            segment = segment[len(_SSE_DATA_PREFIX) :]
        segment = segment.strip()
        return None if (not segment or segment == _SSE_DONE_MARKER) else segment


def _encode_string_header(name: str, value: str) -> bytes:
    name_bytes = name.encode("utf-8")
    value_bytes = value.encode("utf-8")
    return (
        struct.pack("!B", len(name_bytes))
        + name_bytes
        + struct.pack("!BH", _HEADER_TYPE_STRING, len(value_bytes))
        + value_bytes
    )


def _encode_payload_part(payload: bytes) -> bytes:
    """Encode `payload` as one AWS event-stream ``PayloadPart`` message."""
    headers = b"".join(
        _encode_string_header(name, value) for name, value in _PAYLOAD_PART_HEADERS
    )
    total_length = _MIN_MESSAGE_LENGTH + len(headers) + len(payload)
    prelude = struct.pack("!II", total_length, len(headers))
    prelude_crc = crc32(prelude) & 0xFFFFFFFF
    prelude_crc_bytes = struct.pack("!I", prelude_crc)
    # The message CRC continues from the prelude CRC (botocore seeds it).
    message_crc = crc32(prelude_crc_bytes + headers + payload, prelude_crc)
    return (
        prelude
        + prelude_crc_bytes
        + headers
        + payload
        + struct.pack("!I", message_crc & 0xFFFFFFFF)
    )


def _decode_message(message: bytes) -> Optional["EventStreamMessage"]:
    """Decode one complete event-stream message, or ``None`` if it is invalid."""
    from botocore.eventstream import EventStreamBuffer, ParserError

    event_stream_buffer = EventStreamBuffer()
    event_stream_buffer.add_data(message)
    try:
        return next(event_stream_buffer)
    except (ParserError, StopIteration):
        return None


def _is_payload_part(event: "EventStreamMessage") -> bool:
    return (
        event.headers.get(":message-type") == "event"
        and event.headers.get(":event-type") == "PayloadPart"
    )


def _is_json(frame: str) -> bool:
    try:
        json.loads(frame)
    except json.JSONDecodeError:
        return False
    return True


class _EventStreamReframer:
    """Re-frames an event-stream byte stream to one JSON body per PayloadPart.

    Messages that are not decodable ``PayloadPart`` events are forwarded
    unchanged so litellm handles them (and any errors) exactly as before.
    """

    def __init__(self) -> None:
        self._pending = b""
        self._passthrough = False
        self._assembler = _SageMakerSSEFrameAssembler()
        # A multi-byte character can be split across PayloadParts.
        self._text_decoder = codecs.getincrementaldecoder("utf-8")(errors="replace")

    def feed(self, data: bytes) -> Iterator[bytes]:
        """Yield re-framed messages for every message completed by `data`."""
        self._pending += data
        while not self._passthrough and len(self._pending) >= _PRELUDE_LENGTH:
            (total_length,) = struct.unpack("!I", self._pending[:4])
            if not _MIN_MESSAGE_LENGTH <= total_length <= _MAX_MESSAGE_LENGTH:
                # Unframeable bytes: stop re-framing and let litellm's
                # EventStreamBuffer raise on them as it would unpatched.
                self._passthrough = True
                break
            if len(self._pending) < total_length:
                return
            message = self._pending[:total_length]
            self._pending = self._pending[total_length:]
            yield from self._reframe_message(message)
        if self._passthrough and self._pending:
            yield self._pending
            self._pending = b""

    def flush(self) -> Iterator[bytes]:
        """Yield any final frame, then any bytes that never formed a message."""
        tail_text = self._text_decoder.decode(b"", final=True)
        yield from self._encode_frames(self._assembler.feed(tail_text))
        yield from self._encode_frames(self._assembler.flush())
        if self._pending:
            yield self._pending
            self._pending = b""

    def _reframe_message(self, message: bytes) -> Iterator[bytes]:
        event = _decode_message(message)
        if event is None or not _is_payload_part(event):
            yield message
            return
        text = self._text_decoder.decode(event.payload)
        yield from self._encode_frames(self._assembler.feed(text))

    @staticmethod
    def _encode_frames(frames: Iterator[str]) -> Iterator[bytes]:
        for frame in frames:
            if _is_json(frame):
                yield _encode_payload_part(frame.encode("utf-8"))
                continue
            # Forwarding it would leave it in litellm's buffer and poison
            # every later frame. `frame` is LLM content: DEBUG only.
            structlogger.error(
                "litellm_sagemaker_patch.unparseable_frame",
                event_info="Dropping a SageMaker SSE frame that is not valid JSON.",
                frame_length=len(frame),
            )
            structlogger.debug(
                "litellm_sagemaker_patch.unparseable_frame.content", frame=frame
            )


def _reframe_event_stream(iterator: Iterator[bytes]) -> Iterator[bytes]:
    reframer = _EventStreamReframer()
    for data in iterator:
        yield from reframer.feed(data)
    yield from reframer.flush()


async def _areframe_event_stream(
    iterator: AsyncIterator[bytes],
) -> AsyncIterator[bytes]:
    reframer = _EventStreamReframer()
    async for data in iterator:
        for message in reframer.feed(data):
            yield message
    for message in reframer.flush():
        yield message


def _make_patched_iter_bytes(
    original_iter_bytes: Callable[..., Iterator[Any]],
) -> Callable[..., Iterator[Any]]:
    @functools.wraps(original_iter_bytes)
    def patched_iter_bytes(
        self: "AWSEventStreamDecoder", iterator: Iterator[bytes]
    ) -> Iterator[Any]:
        if self.is_messages_api:
            iterator = _reframe_event_stream(iterator)
        yield from original_iter_bytes(self, iterator)

    return patched_iter_bytes


def _make_patched_aiter_bytes(
    original_aiter_bytes: Callable[..., AsyncIterator[Any]],
) -> Callable[..., AsyncIterator[Any]]:
    @functools.wraps(original_aiter_bytes)
    async def patched_aiter_bytes(
        self: "AWSEventStreamDecoder", iterator: AsyncIterator[bytes]
    ) -> AsyncIterator[Any]:
        if self.is_messages_api:
            iterator = _areframe_event_stream(iterator)
        async for chunk in original_aiter_bytes(self, iterator):
            yield chunk

    return patched_aiter_bytes


def install_sagemaker_event_stream_patch() -> None:
    """Patch litellm's SageMaker ``AWSEventStreamDecoder`` in place.

    Idempotent. If litellm no longer exposes the class or methods this patch
    wraps, logs a structured ERROR and leaves litellm unpatched rather than
    raising: that degrades ``sagemaker_chat`` streaming to the known bug but
    must not crash Rasa processes that never use SageMaker.
    """
    global _sagemaker_patch_installed, _ORIGINAL_ITER_BYTES, _ORIGINAL_AITER_BYTES
    if _sagemaker_patch_installed:
        return

    try:
        from litellm.llms.sagemaker.common_utils import AWSEventStreamDecoder
    except ImportError as e:
        structlogger.error(
            "litellm_sagemaker_patch.import_failed",
            event_info=(
                "Could not import litellm's SageMaker AWSEventStreamDecoder; "
                "the ENG-3400 streaming data-loss fix was not installed."
            ),
            error=str(e),
        )
        return

    if not (
        hasattr(AWSEventStreamDecoder, "iter_bytes")
        and hasattr(AWSEventStreamDecoder, "aiter_bytes")
    ):
        structlogger.error(
            "litellm_sagemaker_patch.unexpected_shape",
            event_info=(
                "litellm's AWSEventStreamDecoder no longer exposes "
                "iter_bytes/aiter_bytes; the ENG-3400 streaming data-loss "
                "fix was not installed."
            ),
        )
        return

    _ORIGINAL_ITER_BYTES = AWSEventStreamDecoder.iter_bytes
    _ORIGINAL_AITER_BYTES = AWSEventStreamDecoder.aiter_bytes
    # Deliberate monkeypatch of a third-party class; see the module docstring.
    AWSEventStreamDecoder.iter_bytes = _make_patched_iter_bytes(  # type: ignore[method-assign]
        _ORIGINAL_ITER_BYTES
    )
    AWSEventStreamDecoder.aiter_bytes = _make_patched_aiter_bytes(  # type: ignore[method-assign]
        _ORIGINAL_AITER_BYTES
    )
    _sagemaker_patch_installed = True
